    D("lip-metabolic-syndrome", "Metabolic Syndrome", "A cluster of central obesity, high TG, low HDL, high fasting glucose, and high BP – 3 or more criteria makes the diagnosis – and an ASCVD risk enhancer.", [
      S("criteria", "Diagnostic Criteria", "<p>Diagnosed with <strong>3 or more</strong> of:</p>" + metSynTable + Mn("Waist, TG, HDL, Sugar, Pressure", "40/35 waist, TG 150, HDL 40/50, glucose 100, BP 130/85 – any 3.")),
      S("significance", "Why It Matters", "<p>Metabolic syndrome is an <strong>ASCVD risk enhancer</strong>: in a borderline (5–&lt;7.5%) or intermediate-risk patient it supports starting a statin. Manage it with lifestyle – weight loss, exercise, ↓ saturated fat, ↓ carbs/alcohol for high TG, and control of BP and glucose.</p>" + enhancersList)
    ], [
      Q("criteria", "How many criteria are needed to diagnose metabolic syndrome?", ["3 or more", "2 or more", "4 or more", "All 5"], 0, "Metabolic syndrome is diagnosed with 3+ of: waist, TG, HDL, fasting glucose, BP criteria."),
      Q("criteria", "What waist circumference meets the metabolic syndrome criterion for a woman?", [">35 inches", ">30 inches", ">40 inches", ">45 inches"], 0, "Waist >40 inches in men and >35 inches in women."),
      Q("criteria", "Which HDL value meets the metabolic syndrome criterion for a woman?", ["<50 mg/dL", "<40 mg/dL", "<60 mg/dL", "<35 mg/dL"], 0, "HDL <40 in men or <50 in women."),
      Q("criteria", "Which blood pressure meets the metabolic syndrome criterion?", ["SBP ≥130 and/or DBP ≥85", "SBP ≥140 and/or DBP ≥90", "SBP ≥120 only", "DBP ≥95 only"], 0, "BP criterion: systolic ≥130 and/or diastolic ≥85 mmHg."),
      Q("criteria", "A 47-year-old man has BP 132/78 on lisinopril, TG 178, and HDL 35. Waist and glucose are unknown. Does he meet metabolic syndrome criteria?", ["Yes – BP, TG, and HDL already make 3", "No – waist circumference is required", "No – only 2 criteria are met", "Yes – but only because he smokes"], 0, "SBP ≥130, TG ≥150, and HDL <40 (male) are three criteria, enough for the diagnosis."),
      Q("criteria", "A 58-year-old woman has BP 148/81, TG 192, HDL 42, and a normal fasting glucose. How many metabolic syndrome criteria does she meet from these values?", ["3 – BP, TG, and HDL", "2 – BP and TG only", "1 – BP only", "0"], 0, "SBP ≥130, TG ≥150, and HDL <50 for a woman = 3 criteria: metabolic syndrome."),
      Q("criteria", "Which fasting glucose meets the metabolic syndrome criterion?", ["≥100 mg/dL", "≥126 mg/dL", "≥140 mg/dL", "≥200 mg/dL"], 0, "Fasting glucose ≥100 mg/dL."),
      Q("significance", "How does metabolic syndrome affect a borderline-risk patient’s statin decision?", ["As a risk enhancer, it supports a discussion of moderate-intensity statin", "It mandates high-intensity statin regardless of risk", "It has no role in statin decisions", "It means statins are contraindicated"], 0, "Metabolic syndrome is an ASCVD risk enhancer; with borderline risk (5–<7.5%), enhancers prompt a moderate-intensity statin discussion.")
    ])
